paragraph.math:
$$W\textbf{y} = \begin{bmatrix}
      w_{1} & 0 & \cdots & 0 \\
      0 & w_{2} & & \\
       \vdots & & \ddots & \vdots \\
      0 & & \cdots & w_{n}
      \end{bmatrix}~\left\lbrack \begin{array}{r}
      y_{1} \\
      y_{2} \\
       \vdots \\
      y_{n}
      \end{array} \right\rbrack = \left\lbrack \begin{array}{r}
      {w_{1}y_{1}} \\
      {w_{2}y_{2}} \\
       \vdots \\
      {w_{n}y_{n}}
      \end{array} \right\rbrack$$

$$\begin{matrix}
      \widehat{p} & = & {\frac{\left\langle g\text{,~}p_{0} \right\rangle}{\left\langle p_{0}\text{,~}p_{0} \right\rangle}p_{0} + \frac{\left\langle g\text{,~}p_{1} \right\rangle}{\left\langle p_{1}\text{,~}p_{1} \right\rangle}p_{1} + \frac{\left\langle g\text{,~}p_{2} \right\rangle}{\left\langle p_{2}\text{,~}p_{2} \right\rangle}p_{2}} \\
       & = & {\frac{20}{5}p_{0} - \frac{1}{10}p_{1} - \frac{7}{14}p_{2}}
      \end{matrix}$$

$$\begin{array}{lll}
      \left\langle \text{cos~}mt\text{,~cos~}nt \right\rangle & = & {\int_{0}^{2\pi}\text{cos}\,mt\text{~cos}\,nt\,dt} \\
       & = & {\frac{1}{2}\int_{0}^{2\pi}\text{[cos}(mt + nt) + \text{cos}\left( mt - nt\text{)} \right.\text{]}dt} \\
       & = & {\left. \frac{1}{2}\left\lbrack \frac{\sin(mt + nt)}{m + n} + \frac{\sin(mt - nt)}{m - n} \right\rbrack \right|_{0}^{2\pi} = 0}
      \end{array}$$

$$\begin{matrix}
      a_{k} & = & {\frac{1}{\pi}\int_{0}^{2\pi} t\text{~cos~}kt dt = \frac{1}{\pi}\left\lbrack \frac{1}{k^{2}}\text{cos~}kt + \frac{t}{k}\text{sin~}kt \right\rbrack_{0}^{2\pi} = 0} \\
      b_{k} & = & {\frac{1}{\pi}\int_{0}^{2\pi} t\text{~sin~}kt dt = \frac{1}{\pi}\left\lbrack \frac{1}{k^{2}}\text{sin~}kt - \frac{t}{k}\text{cos~}kt \right\rbrack_{0}^{2\pi} = - \frac{2}{k}}
      \end{matrix}$$
